import type {
  ConflictInfo,
  ConflictPolicy,
  MergeDocumentsResult,
  MergeOutcome,
  SyncDocument,
} from './types'

/** Positive if a is newer than b. */
export function compareUpdatedAt(a: string, b: string): number {
  const ta = Date.parse(a)
  const tb = Date.parse(b)
  if (Number.isNaN(ta) && Number.isNaN(tb)) return 0
  if (Number.isNaN(ta)) return -1
  if (Number.isNaN(tb)) return 1
  return ta - tb
}

/** Effective timestamp for LWW / tombstone ordering. */
export function effectiveTime(doc: SyncDocument): string {
  if (doc.deletedAt) {
    return compareUpdatedAt(doc.deletedAt, doc.updatedAt) >= 0
      ? doc.deletedAt
      : doc.updatedAt
  }
  return doc.updatedAt
}

function isDeleted(doc: SyncDocument): boolean {
  return Boolean(doc.deletedAt)
}

/**
 * Tie-break when timestamps equal: lexicographically greater deviceId wins
 * (stable, deterministic across machines).
 */
function compareDocsLww(a: SyncDocument, b: SyncDocument): number {
  const byTime = compareUpdatedAt(effectiveTime(a), effectiveTime(b))
  if (byTime !== 0) return byTime
  if (a.deviceId === b.deviceId) return a.rev - b.rev
  return a.deviceId < b.deviceId ? -1 : a.deviceId > b.deviceId ? 1 : 0
}

function sameVersion(a: SyncDocument, b: SyncDocument): boolean {
  return (
    a.updatedAt === b.updatedAt &&
    a.deviceId === b.deviceId &&
    a.rev === b.rev &&
    (a.deletedAt ?? null) === (b.deletedAt ?? null)
  )
}

/** True when neither side is a direct descendant of the other. */
function bothDiverged(local: SyncDocument, remote: SyncDocument): boolean {
  const localFromRemote =
    Boolean(local.baseUpdatedAt) && local.baseUpdatedAt === remote.updatedAt
  const remoteFromLocal =
    Boolean(remote.baseUpdatedAt) && remote.baseUpdatedAt === local.updatedAt
  if (localFromRemote || remoteFromLocal) return false
  if (
    local.updatedAt === remote.updatedAt &&
    local.deviceId === remote.deviceId
  ) {
    return false
  }
  return true
}

/**
 * When choosing a winner, keep tombstone semantics: if the winning side is a
 * delete, preserve deletedAt; if live wins over older tombstone, clear delete.
 */
function resolveTombstonePair(
  preferred: SyncDocument,
  other: SyncDocument,
): SyncDocument {
  const prefTime = effectiveTime(preferred)
  const otherTime = effectiveTime(other)

  if (isDeleted(preferred) && isDeleted(other)) {
    return compareUpdatedAt(prefTime, otherTime) >= 0 ? preferred : other
  }

  if (isDeleted(preferred)) {
    // Delete wins only if tombstone is newer than the other live update
    if (compareUpdatedAt(prefTime, other.updatedAt) >= 0) return preferred
    return { ...other, deletedAt: null }
  }

  if (isDeleted(other)) {
    // Live preferred: resurrect if live is newer than tombstone
    if (compareUpdatedAt(preferred.updatedAt, otherTime) >= 0) {
      return { ...preferred, deletedAt: null }
    }
    return other
  }

  return preferred
}

function lwwWinner(local: SyncDocument, remote: SyncDocument): SyncDocument {
  return compareDocsLww(local, remote) >= 0
    ? resolveTombstonePair(local, remote)
    : resolveTombstonePair(remote, local)
}

/**
 * Merge one local + one remote document for the same id.
 *
 * Rules:
 * 1. Missing side → keep the other
 * 2. Same version → keep local
 * 3. One side based on the other (baseUpdatedAt) → take the child
 * 4. Both diverged → lww or conflict
 * 5. Tombstones: newer delete wins; newer live resurrects
 */
export function mergeOne(
  local: SyncDocument | null | undefined,
  remote: SyncDocument | null | undefined,
  policy: ConflictPolicy,
): MergeOutcome {
  if (!local && !remote) {
    throw new Error('mergeOne requires at least one document')
  }
  if (!local) return { kind: 'keep', doc: remote! }
  if (!remote) return { kind: 'keep', doc: local }
  if (sameVersion(local, remote)) return { kind: 'keep', doc: local }

  // Local is a direct child of remote's current version
  if (local.baseUpdatedAt && local.baseUpdatedAt === remote.updatedAt) {
    return { kind: 'keep', doc: resolveTombstonePair(local, remote) }
  }
  // Remote is a direct child of local's current version
  if (remote.baseUpdatedAt && remote.baseUpdatedAt === local.updatedAt) {
    return { kind: 'keep', doc: resolveTombstonePair(remote, local) }
  }

  const diverged = bothDiverged(local, remote)

  // Tombstone vs live without shared lineage: LWW on effective time, or
  // surface conflict in detect mode when both truly diverged.
  if (isDeleted(local) !== isDeleted(remote)) {
    if (policy === 'detect' && diverged) {
      return { kind: 'conflict', local, remote }
    }
    return { kind: 'keep', doc: lwwWinner(local, remote) }
  }

  if (policy === 'detect' && diverged) {
    return { kind: 'conflict', local, remote }
  }

  return { kind: 'keep', doc: lwwWinner(local, remote) }
}

/**
 * Merge two lists of documents (typically same collection). Different ids kept.
 * Tombstones are retained so sync can write them to the folder.
 */
export function mergeDocuments(
  localDocs: SyncDocument[],
  remoteDocs: SyncDocument[],
  policy: ConflictPolicy,
): MergeDocumentsResult {
  const byId = new Map<string, { local?: SyncDocument; remote?: SyncDocument }>()

  for (const doc of localDocs) {
    if (!doc?.id) continue
    const slot = byId.get(doc.id) ?? {}
    slot.local = doc
    byId.set(doc.id, slot)
  }
  for (const doc of remoteDocs) {
    if (!doc?.id) continue
    const slot = byId.get(doc.id) ?? {}
    slot.remote = doc
    byId.set(doc.id, slot)
  }

  const docs: SyncDocument[] = []
  const conflicts: ConflictInfo[] = []

  for (const [id, { local, remote }] of byId) {
    const outcome = mergeOne(local, remote, policy)
    if (outcome.kind === 'keep') {
      docs.push(outcome.doc)
    } else {
      conflicts.push({
        collection: outcome.local.collection || outcome.remote.collection,
        id,
        local: outcome.local,
        remote: outcome.remote,
      })
      // Keep local in working set until resolved (do not clobber)
      docs.push(outcome.local)
    }
  }

  docs.sort((a, b) => compareUpdatedAt(b.updatedAt, a.updatedAt))
  return { docs, conflicts }
}

/** Apply LWW between two docs. */
export function pickNewer(a: SyncDocument, b: SyncDocument): SyncDocument {
  return lwwWinner(a, b)
}
