import { getOrCreateDeviceId } from './deviceId'
import {
  ensurePermission,
  getAppDir,
  isFolderSyncSupported,
  listCollectionNames,
  pickDirectory,
  readCollectionDocs,
  writeDocToFolder,
  writeMeta,
} from './folder'
import { openLocalSyncDb, type LocalSyncDb } from './idb'
import { mergeDocuments } from './merge'
import type {
  ConflictChoice,
  ConflictHandler,
  ConflictInfo,
  ConflictPolicy,
  CreateLocalSyncOptions,
  LocalSyncState,
  SyncDocument,
} from './types'

export interface LocalSync {
  readonly appId: string
  readonly deviceId: string
  isSupported: () => boolean
  getState: () => LocalSyncState
  subscribe: (listener: (s: LocalSyncState) => void) => () => void
  init: () => Promise<LocalSyncState>
  mapFolder: () => Promise<LocalSyncState>
  unmapFolder: () => Promise<LocalSyncState>
  requestPermission: () => Promise<boolean>
  put: <T = unknown>(
    collection: string,
    id: string,
    payload: T,
  ) => Promise<SyncDocument<T>>
  get: <T = unknown>(
    collection: string,
    id: string,
  ) => Promise<SyncDocument<T> | null>
  list: <T = unknown>(collection: string) => Promise<SyncDocument<T>[]>
  delete: (collection: string, id: string) => Promise<SyncDocument | null>
  sync: () => Promise<LocalSyncState>
  onConflict: (handler: ConflictHandler | null) => void
  listConflicts: () => ConflictInfo[]
  resolveConflict: (
    collection: string,
    id: string,
    choice: ConflictChoice | SyncDocument | unknown,
  ) => Promise<SyncDocument>
}

export function createLocalSync(options: CreateLocalSyncOptions): LocalSync {
  const appId = options.appId
  if (!appId || /[/\\]/.test(appId)) {
    throw new Error('createLocalSync: appId is required and must not contain slashes')
  }

  const conflictPolicy: ConflictPolicy = options.conflictPolicy ?? 'lww'
  const dbName = options.dbName ?? `localsync-${appId}`
  const deviceIdKey = options.deviceIdKey ?? `localsync-device-id`
  const deviceId = getOrCreateDeviceId(deviceIdKey)
  const supported = isFolderSyncSupported()

  let db: LocalSyncDb | null = null
  let cachedHandle: FileSystemDirectoryHandle | null = null
  let conflictHandler: ConflictHandler | null = null
  const conflicts = new Map<string, ConflictInfo>()
  const listeners = new Set<(s: LocalSyncState) => void>()

  let state: LocalSyncState = {
    status: supported ? 'unmapped' : 'unsupported',
    folderName: null,
    lastSyncedAt: null,
    lastError: null,
    supported,
    pendingConflicts: 0,
  }

  function conflictKey(collection: string, id: string): string {
    return `${collection}/${id}`
  }

  function getState(): LocalSyncState {
    return {
      ...state,
      pendingConflicts: conflicts.size,
      supported: isFolderSyncSupported(),
    }
  }

  function setState(partial: Partial<LocalSyncState>): void {
    state = {
      ...state,
      ...partial,
      supported: isFolderSyncSupported(),
      pendingConflicts: conflicts.size,
    }
    const snapshot = getState()
    for (const l of listeners) {
      try {
        l(snapshot)
      } catch {
        /* ignore */
      }
    }
  }

  function subscribe(listener: (s: LocalSyncState) => void): () => void {
    listeners.add(listener)
    return () => {
      listeners.delete(listener)
    }
  }

  async function ensureDb(): Promise<LocalSyncDb> {
    if (db) return db
    if (typeof indexedDB === 'undefined') {
      throw new Error('IndexedDB is not available')
    }
    db = await openLocalSyncDb(dbName)
    return db
  }

  async function init(): Promise<LocalSyncState> {
    if (!isFolderSyncSupported()) {
      setState({
        status: 'unsupported',
        folderName: null,
        lastError: null,
      })
      try {
        await ensureDb()
      } catch {
        /* IDB-only still useful when present */
      }
      return getState()
    }

    const store = await ensureDb()
    const handle = await store.getHandle()
    if (!handle) {
      cachedHandle = null
      setState({ status: 'unmapped', folderName: null, lastError: null })
      return getState()
    }

    cachedHandle = handle
    const ok = await ensurePermission(handle, 'readwrite')
    if (!ok) {
      setState({
        status: 'permission_needed',
        folderName: handle.name,
        lastError: 'Permission needed to access the sync folder.',
      })
      return getState()
    }

    setState({
      status: 'mapped',
      folderName: handle.name,
      lastError: null,
    })
    return getState()
  }

  async function mapFolder(): Promise<LocalSyncState> {
    if (!isFolderSyncSupported()) {
      setState({
        status: 'unsupported',
        lastError:
          'Folder sync is not supported in this browser (use Chrome/Edge/Desktop Safari). Local IndexedDB still works.',
      })
      return getState()
    }

    try {
      const handle = await pickDirectory(`localsync-${appId}`)
      const store = await ensureDb()
      await store.setHandle(handle)
      cachedHandle = handle
      setState({
        status: 'mapped',
        folderName: handle.name,
        lastError: null,
      })
    } catch (e) {
      const aborted =
        e instanceof DOMException &&
        (e.name === 'AbortError' || e.name === 'NotAllowedError')
      if (!aborted) {
        setState({
          lastError: e instanceof Error ? e.message : String(e),
        })
      }
    }
    return getState()
  }

  async function unmapFolder(): Promise<LocalSyncState> {
    cachedHandle = null
    try {
      const store = await ensureDb()
      await store.setHandle(null)
    } catch {
      /* ignore */
    }
    setState({
      status: isFolderSyncSupported() ? 'unmapped' : 'unsupported',
      folderName: null,
      lastSyncedAt: null,
      lastError: null,
    })
    return getState()
  }

  async function requestPermission(): Promise<boolean> {
    const store = await ensureDb()
    const handle = cachedHandle ?? (await store.getHandle())
    if (!handle) return false
    cachedHandle = handle
    const ok = await ensurePermission(handle, 'readwrite')
    if (ok) {
      setState({
        status: 'mapped',
        folderName: handle.name,
        lastError: null,
      })
    } else {
      setState({
        status: 'permission_needed',
        folderName: handle.name,
        lastError: 'Permission needed to access the sync folder.',
      })
    }
    return ok
  }

  async function put<T = unknown>(
    collection: string,
    id: string,
    payload: T,
  ): Promise<SyncDocument<T>> {
    const store = await ensureDb()
    const existing = await store.getDoc(collection, id)
    const now = new Date().toISOString()
    const doc: SyncDocument<T> = {
      version: 1,
      id,
      collection,
      updatedAt: now,
      createdAt: existing?.createdAt ?? now,
      deletedAt: null,
      deviceId,
      rev: (existing?.deviceId === deviceId ? existing.rev : 0) + 1,
      baseUpdatedAt: existing?.updatedAt,
      payload,
    }
    await store.putDoc(doc as SyncDocument)
    conflicts.delete(conflictKey(collection, id))
    setState({})

    // Best-effort schedule folder write when mapped
    void writeThrough(doc as SyncDocument)
    return doc
  }

  async function writeThrough(doc: SyncDocument): Promise<void> {
    if (state.status !== 'mapped' || !cachedHandle) return
    try {
      const ok = await ensurePermission(cachedHandle, 'readwrite')
      if (!ok) return
      const appDir = await getAppDir(cachedHandle, appId, true)
      await writeDocToFolder(appDir, doc)
      await writeMeta(appDir, appId)
    } catch {
      /* best-effort */
    }
  }

  async function get<T = unknown>(
    collection: string,
    id: string,
  ): Promise<SyncDocument<T> | null> {
    const store = await ensureDb()
    const doc = await store.getDoc(collection, id)
    if (!doc || doc.deletedAt) return null
    return doc as SyncDocument<T>
  }

  async function list<T = unknown>(
    collection: string,
  ): Promise<SyncDocument<T>[]> {
    const store = await ensureDb()
    const docs = await store.listDocs(collection)
    return docs
      .filter((d) => !d.deletedAt)
      .sort((a, b) => (a.updatedAt < b.updatedAt ? 1 : -1)) as SyncDocument<T>[]
  }

  async function deleteDoc(
    collection: string,
    id: string,
  ): Promise<SyncDocument | null> {
    const store = await ensureDb()
    const existing = await store.getDoc(collection, id)
    if (!existing) return null
    const now = new Date().toISOString()
    const doc: SyncDocument = {
      ...existing,
      updatedAt: now,
      deletedAt: now,
      deviceId,
      rev: (existing.deviceId === deviceId ? existing.rev : 0) + 1,
      baseUpdatedAt: existing.updatedAt,
      payload: existing.payload,
    }
    await store.putDoc(doc)
    conflicts.delete(conflictKey(collection, id))
    setState({})
    void writeThrough(doc)
    return doc
  }

  function rememberConflicts(list: ConflictInfo[]): void {
    for (const c of list) {
      conflicts.set(conflictKey(c.collection, c.id), c)
    }
    setState({ pendingConflicts: conflicts.size })
  }

  async function applyHandler(
    conflict: ConflictInfo,
  ): Promise<SyncDocument | null> {
    if (!conflictHandler) return null
    const result = await conflictHandler(conflict)
    if (result === 'local') return conflict.local
    if (result === 'remote') return conflict.remote
    return result
  }

  async function sync(): Promise<LocalSyncState> {
    const store = await ensureDb()

    if (!isFolderSyncSupported()) {
      setState({ status: 'unsupported' })
      return getState()
    }

    let handle = cachedHandle
    if (!handle) {
      handle = await store.getHandle()
      cachedHandle = handle
    }
    if (!handle) {
      setState({ status: 'unmapped', folderName: null })
      return getState()
    }

    const permitted = await ensurePermission(handle, 'readwrite')
    if (!permitted) {
      setState({
        status: 'permission_needed',
        folderName: handle.name,
        lastError: 'Permission needed to access the sync folder.',
      })
      return getState()
    }

    setState({ status: 'syncing', folderName: handle.name, lastError: null })

    try {
      const appDir = await getAppDir(handle, appId, true)
      const localAll = await store.listAllDocs()
      const localByCollection = groupByCollection(localAll)

      const remoteCollections = new Set<string>([
        ...Object.keys(localByCollection),
        ...(await listCollectionNames(appDir)),
      ])

      const newConflicts: ConflictInfo[] = []

      for (const collection of remoteCollections) {
        const localDocs = localByCollection[collection] ?? []
        const remoteDocs = await readCollectionDocs(appDir, collection)
        const { docs, conflicts: colConflicts } = mergeDocuments(
          localDocs,
          remoteDocs,
          conflictPolicy,
        )

        const finalById = new Map<string, SyncDocument>()
        for (const doc of docs) {
          finalById.set(doc.id, doc)
        }

        for (const c of colConflicts) {
          const handled = await applyHandler(c)
          if (handled) {
            finalById.set(c.id, handled)
          } else {
            newConflicts.push(c)
            finalById.set(c.id, c.local)
          }
        }

        for (const doc of finalById.values()) {
          await store.putDoc(doc)
          await writeDocToFolder(appDir, doc)
        }
      }

      // Clear conflicts that were resolved; keep unresolved
      conflicts.clear()
      rememberConflicts(newConflicts)

      await writeMeta(appDir, appId)
      const now = new Date().toISOString()
      setState({
        status: 'mapped',
        folderName: handle.name,
        lastSyncedAt: now,
        lastError: null,
      })
    } catch (e) {
      const message = e instanceof Error ? e.message : String(e)
      setState({
        status: 'error',
        folderName: handle.name,
        lastError: message,
      })
    }

    return getState()
  }

  function listConflicts(): ConflictInfo[] {
    return Array.from(conflicts.values())
  }

  function onConflict(handler: ConflictHandler | null): void {
    conflictHandler = handler
  }

  async function resolveConflict(
    collection: string,
    id: string,
    choice: ConflictChoice | SyncDocument | unknown,
  ): Promise<SyncDocument> {
    const store = await ensureDb()
    const key = conflictKey(collection, id)
    const info = conflicts.get(key)
    const local = info?.local ?? (await store.getDoc(collection, id))
    if (!local && !info?.remote) {
      throw new Error(`No conflict or document for ${collection}/${id}`)
    }

    let winner: SyncDocument
    if (choice === 'local') {
      if (!local) throw new Error('No local document')
      winner = local
    } else if (choice === 'remote') {
      if (!info?.remote) throw new Error('No remote document in conflict')
      winner = info.remote
    } else if (
      choice &&
      typeof choice === 'object' &&
      'id' in (choice as object) &&
      'updatedAt' in (choice as object) &&
      'payload' in (choice as object)
    ) {
      winner = choice as SyncDocument
    } else {
      // Treat as merged payload
      const base = local ?? info!.remote
      const now = new Date().toISOString()
      winner = {
        ...base,
        updatedAt: now,
        deletedAt: null,
        deviceId,
        rev: (base.deviceId === deviceId ? base.rev : 0) + 1,
        baseUpdatedAt: base.updatedAt,
        payload: choice,
      }
    }

    // Stamp as a new local edit resolving the conflict
    if (choice === 'local' || choice === 'remote') {
      const now = new Date().toISOString()
      winner = {
        ...winner,
        updatedAt: now,
        deviceId,
        rev: (winner.deviceId === deviceId ? winner.rev : 0) + 1,
        baseUpdatedAt: info
          ? [info.local.updatedAt, info.remote.updatedAt].sort().at(-1)
          : winner.updatedAt,
      }
    }

    await store.putDoc(winner)
    conflicts.delete(key)
    setState({})
    void writeThrough(winner)
    return winner
  }

  return {
    appId,
    deviceId,
    isSupported: () => isFolderSyncSupported(),
    getState,
    subscribe,
    init,
    mapFolder,
    unmapFolder,
    requestPermission,
    put,
    get,
    list,
    delete: deleteDoc,
    sync,
    onConflict,
    listConflicts,
    resolveConflict,
  }
}

function groupByCollection(
  docs: SyncDocument[],
): Record<string, SyncDocument[]> {
  const out: Record<string, SyncDocument[]> = {}
  for (const doc of docs) {
    if (!out[doc.collection]) out[doc.collection] = []
    out[doc.collection].push(doc)
  }
  return out
}

